// Writes shared/src/catalog.generated.js: the 30 sites joined with the trained model's
// predictions. The client uses it when no API is configured (static hosting).
// Run after retraining:  npm run catalog   (npm run train does both).
import { writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { sites } from "../../shared/src/sites.js";
import { createEngine } from "../src/services/engine.service.js";
import { buildCatalog } from "../src/services/catalog.service.js";

export const renderCatalog = () =>
  "// GENERATED by server/scripts/generate-catalog.js. Do not edit by hand.\n" +
  "export default " +
  JSON.stringify(buildCatalog(sites, createEngine()), null, 1) +
  ";\n";

const out = fileURLToPath(new URL("../../shared/src/catalog.generated.js", import.meta.url));
if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const text = renderCatalog();
  writeFileSync(out, text);
  const missing = JSON.parse(text.slice(text.indexOf("{"), -2)).locations.filter((s) => !s.prediction);
  console.log(`Wrote ${out}`);
  if (missing.length)
    console.warn("No dataset row for:", missing.map((s) => s.datasetName).join(", "));
}
export { out as catalogPath };
